 // Computes C = A * B. C is NOT zeroed by the caller. Any number of threads may be
 // used (std::thread is available); n is any size from 1 to 2048.
+constexpr int TILE_K = 73; // size of k‑tile (swept)
+
 extern "C" void matmul(int n, const float* A, const float* B, float* C) {
-    for (int i = 0; i < n; ++i)
-        for (int j = 0; j < n; ++j) {
-            float s = 0.0f;
-            for (int k = 0; k < n; ++k) s += A[i * n + k] * B[k * n + j];
-            C[i * n + j] = s;
-        }
+    // zero the result matrix
+    std::fill(C, C + (size_t)n * n, 0.0f);
+
+    // determine number of threads
+    unsigned thr = std::thread::hardware_concurrency();
+    if (thr == 0) thr = 1;
+    unsigned rows_per_thread = (n + thr - 1) / thr;
+
+    std::vector<std::thread> ts;
+    ts.reserve(thr);
+
+    for (unsigned t = 0; t < thr; ++t) {
+        int start = (int)(t * rows_per_thread);
+        int end   = std::min(start + (int)rows_per_thread, n);
+        if (start >= end) continue;
+
+        ts.emplace_back([=, &A, &B, &C]() {
+            for (int i = start; i < end; ++i) {
+                for (int kk = 0; kk < n; kk += TILE_K) {
+                    int k_end = std::min(kk + TILE_K, n);
+                    for (int k = kk; k < k_end; ++k) {
+                        float a = A[i * n + k];
+                        int j = 0;
+                        for (; j + 3 < n; j += 4) {
+                            float b0 = B[k * n + j];
+                            float b1 = B[k * n + j + 1];
+                            float b2 = B[k * n + j + 2];
+                            float b3 = B[k * n + j + 3];
+                            C[i * n + j]     += a * b0;
+                            C[i * n + j + 1] += a * b1;
+                            C[i * n + j + 2] += a * b2;
+                            C[i * n + j + 3] += a * b3;
+                        }
+                        for (; j < n; ++j) {
+                            C[i * n + j] += a * B[k * n + j];
+                        }
+                    }
+                }
+            }
+        });
+    }
+
+    for (auto& t : ts) t.join();
 }
 // OMEGA-BLOCK-END
